<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import {
  pickPoMatchText,
  type PoMatchDistribution,
  type PoMatchPass,
  type PoMatchStage,
  type PoMatchText,
} from 'src/services/analytics/PoMatchExplanationService';

interface FlowPass {
  key: string;
  number: string;
  titleLines: string[];
  detailLines: string[];
  titleY: number;
  detailY: number;
  h: number;
  tooltip: string;
  aria: string;
  runs: boolean;
  state: string | null;
  stateClass: string;
  y: number;
  cy: number;
  /** Top of the box the red "No match" arrow leads to, or null at the end. */
  nextY: number | null;
  docCount: number;
  barLabel: string;
  pass: PoMatchPass;
}

interface FlowBand {
  key: string;
  no: number;
  titleLines: string[];
  conditionLines: string[];
  conditionY: number;
  rulesY: number;
  ruleLines: string[];
  tooltip: string;
  marker: string;
  state: string | null;
  stateClass: string;
  y: number;
  h: number;
  passes: FlowPass[];
}

interface FlowLayout {
  bands: FlowBand[];
  passes: FlowPass[];
  height: number;
  successY: number;
  noMatchY: number;
  railTop: number | null;
  railBottom: number | null;
}

/**
 * What the single box of a one-pass stage is actually comparing.
 *
 * Presentation, not data: it is a fixed property of the engine's topology, the
 * same way the five stages are, and it is bilingual here for the same reason
 * the API sends both languages — the sentence is drawn from a closed
 * vocabulary, so there is no key to translate and nothing to keep in sync.
 */
const BOX_LABELS: Record<string, PoMatchText> = {
  total_match: {
    en: 'PO line total against the sum of its table lines',
    de: 'Summe der Bestellzeile gegen Summe der Belegzeilen',
  },
  fallback: {
    en: 'Pair the last PO line with the last table line',
    de: 'Letzte Bestellzeile mit letzter Belegzeile paaren',
  },
};

/** Monotonic, so two diagrams on one page never share an SVG marker id. */
let instanceCounter = 0;

/**
 * The PO-match rule set, the path and the cluster distribution — one diagram.
 *
 * Drawn as the product owner's own flow chart: a START pill, five tinted stage
 * bands numbered down the page, the passes of each stage stacked inside it, a
 * "Match found?" decision beside every pass with a green Yes edge onto one
 * green rail into MATCH SUCCESSFUL, and a red "No match" arrow falling to the
 * next pass, the next stage, and finally into NO MATCH FOUND. That shape is
 * not decoration: it is how the engine actually behaves — a hit anywhere stops
 * processing, and everything else falls through — and a diagram that did not
 * show the two exits could not tell a reader why stage 4 ever runs.
 *
 * Inline SVG on purpose (the ticket's own constraint): the topology is FIXED,
 * so a graph library would ship a layout engine to position boxes whose
 * coordinates are arithmetic. Options API with `defineComponent`, no
 * `<script setup>` — the house style.
 *
 * The component decides NOTHING about the customer's configuration. The
 * stages, their passes, the rules inside them and every state arrive in
 * `stages`; this file positions them and colours them. Colour is never the
 * only carrier: every band draws a numbered badge, every state a glyph, and
 * every edge is labelled Yes / No match in words.
 */
export default defineComponent({
  name: 'PoMatchDecisionFlow',

  props: {
    /** Ordered by the API. Rendered in the order given, never re-sorted. */
    stages: {
      type: Array as PropType<PoMatchStage[]>,
      default: () => [],
    },
    mode: {
      type: String as PropType<'ruleset' | 'document' | 'cluster'>,
      default: 'ruleset',
    },
    terminal: {
      type: Object as PropType<{ key: string; label: PoMatchText } | null>,
      default: null,
    },
    distribution: {
      type: Object as PropType<PoMatchDistribution | null>,
      default: null,
    },
    /** The reason there is no path, already localised by the API. */
    traceMissingLabel: {
      type: Object as PropType<PoMatchText | null>,
      default: null,
    },
    /**
     * Compact is for the cluster card, where the diagram sits inside a card
     * that is already dense. It shrinks the boxes; it never drops a stage or a
     * pass, because a diagram missing one would answer a different question.
     */
    compact: { type: Boolean, default: false },
  },

  emits: ['select-pass'],

  data() {
    return {
      /**
       * The SVG marker ids, unique per instance.
       *
       * SVG ids are DOCUMENT-global: the supplier page can render this diagram
       * inside several cluster cards at once, and a shared `url(#arrow)` would
       * resolve to whichever instance mounted first — so the arrowheads of
       * every other copy disappear when it unmounts.
       */
      uid: `pmdf-${(instanceCounter += 1)}`,
    };
  },

  computed: {
    locale(): string {
      return String(this.$i18n?.locale || 'en');
    },

    isCluster(): boolean {
      return this.mode === 'cluster';
    },

    W(): number {
      return this.BAND_W + 248;
    },
    BAND_X(): number {
      return 20;
    },
    BAND_W(): number {
      return this.DIVIDER_X + this.COL_W + 228;
    },
    DIVIDER_X(): number {
      // German compound stage names need their own space, also in compact mode.
      if (this.locale.startsWith('de')) return 290;
      return this.compact ? 222 : 244;
    },
    COL_X(): number {
      return this.DIVIDER_X + 28;
    },
    COL_W(): number {
      return this.compact ? 304 : 340;
    },
    START_W(): number {
      return 152;
    },
    PASS_H(): number {
      return 70;
    },
    PASS_GAP(): number {
      return 44;
    },
    DIA_CX(): number {
      return this.COL_X + this.COL_W + 110;
    },
    DIA_W(): number {
      return 64;
    },
    DIA_H(): number {
      return Math.max(38, this.decisionLines.length * 14 + 16);
    },
    RAIL_X(): number {
      return this.TERM_OK_X + this.TERM_OK_W / 2;
    },
    TERM_OK_X(): number {
      return this.BAND_X + this.BAND_W + 26;
    },
    TERM_OK_W(): number {
      return 176;
    },
    TERM_OK_H(): number {
      return 104 + Math.max(0, this.successLines.length - 1) * 22;
    },
    TERM_NO_X(): number {
      return this.DIA_CX - this.TERM_NO_W / 2;
    },
    TERM_NO_W(): number {
      return 252;
    },
    TERM_NO_H(): number {
      return Math.max(82, this.noMatchLines.length * 22 + 28);
    },
    decisionLines(): string[] {
      return this.wrapLines(this.$t('po_match_flow_decision'), 10);
    },
    successLines(): string[] {
      return this.wrapLines(this.$t('po_match_flow_terminal_matched'), 13);
    },
    noMatchLines(): string[] {
      return this.wrapLines(this.$t('po_match_flow_terminal_no_match'), 15);
    },

    /** The biggest count in the cluster, so the bars share one scale. */
    maxDocCount(): number {
      let max = 0;
      for (const stage of this.stages) {
        for (const pass of stage.passes || []) {
          max = Math.max(max, Number(pass.doc_count || 0));
        }
        max = Math.max(max, Number(stage.doc_count || 0));
      }
      return max;
    },

    traceMissingText(): string {
      return pickPoMatchText(this.traceMissingLabel, this.locale);
    },

    /**
     * Every coordinate on the page, computed once.
     *
     * One pass over the stages rather than a helper per shape: the bands have
     * different heights (stage 3 and stage 5 run a single pass), so every y
     * below a band depends on the ones above it, and scattering that
     * arithmetic across template expressions is how a diagram ends up with
     * arrows pointing at nothing.
     */
    layout(): FlowLayout {
      const bands: FlowBand[] = [];
      const allPasses: FlowPass[] = [];
      let y = 98;

      for (const stage of this.stages) {
        const titleLines = this.wrapLines(
          pickPoMatchText(stage.label, this.locale),
          this.locale.startsWith('de') ? 21 : this.compact ? 18 : 21,
        );
        const conditionLines = this.wrapLines(
          pickPoMatchText(stage.condition, this.locale),
          this.compact ? 23 : 26,
        );
        const ruleLines = this.ruleLines(stage);
        const conditionY = y + 80 + titleLines.length * 22 + 10;
        const rulesY = conditionY + conditionLines.length * 20 + 14;
        const running = (stage.passes || []).filter(
          (pass) => pass.runs !== false,
        );
        const shown = running.length ? running : stage.passes || [];
        const passes: FlowPass[] = shown.map((pass, i) => {
          const number = `${stage.no}.${i + 1}`;
          const titleLines = this.wrapLines(
            `${number} ${this.boxTitle(stage, pass, shown.length)}`,
            this.compact ? 32 : 36,
          );
          const detailLines = this.wrapLines(
            this.boxDetail(pass),
            this.compact ? 32 : 36,
          );
          const textH =
            titleLines.length * 20 +
            (detailLines.length ? 8 + detailLines.length * 18 : 0);
          const count = Number(pass.doc_count || 0);
          const countH = this.isCluster && count ? 28 : 0;
          const h = Math.max(this.PASS_H, textH + 30 + countH, this.DIA_H * 2);
          return {
            key: pass.key,
            number,
            titleLines,
            detailLines,
            titleY: 0,
            detailY: 0,
            y: 0,
            cy: 0,
            h,
            tooltip: this.passTooltip(stage, pass),
            aria: `${number} ${pickPoMatchText(pass.label, this.locale)}`,
            runs: pass.runs !== false,
            state: pass.state,
            stateClass: this.stateClass(pass.state),
            nextY: null,
            docCount: count,
            barLabel: this.barLabel(pass),
            pass,
          };
        });
        const innerH =
          passes.reduce((sum, pass) => sum + pass.h, 0) +
          Math.max(0, passes.length - 1) * this.PASS_GAP;
        const labelH = rulesY - y + ruleLines.length * 18 + 16;
        const h = Math.max(innerH + 44, labelH, 160);
        let passY = y + (h - innerH) / 2;
        for (const pass of passes) {
          const countH = this.isCluster && pass.docCount ? 28 : 0;
          const textH =
            pass.titleLines.length * 20 +
            (pass.detailLines.length ? 8 + pass.detailLines.length * 18 : 0);
          pass.y = passY;
          pass.cy = passY + pass.h / 2;
          pass.titleY = passY + (pass.h - countH - textH) / 2 + 15;
          pass.detailY = pass.titleY + pass.titleLines.length * 20 + 6;
          passY += pass.h + this.PASS_GAP;
          allPasses.push(pass);
        }
        bands.push({
          key: stage.key,
          no: stage.no,
          titleLines,
          conditionLines,
          conditionY,
          rulesY,
          ruleLines,
          tooltip: this.stageTooltip(stage),
          marker: this.stateMarker(stage.state),
          state: stage.state,
          stateClass: this.stateClass(stage.state),
          y,
          h,
          passes,
        });
        y += h + 24;
      }
      allPasses.forEach((pass, i) => {
        pass.nextY = allPasses[i + 1]?.y ?? null;
      });
      const middle =
        bands.find((band) => band.no === 3)?.passes[0] ??
        allPasses[Math.floor(allPasses.length / 2)];
      const successY = Math.max(70, (middle?.cy ?? 150) - this.TERM_OK_H / 2);
      const noMatchY = Math.max(y, successY + this.TERM_OK_H + 30);
      return {
        bands,
        passes: allPasses,
        height: noMatchY + this.TERM_NO_H + 20,
        successY,
        noMatchY,
        railTop: allPasses[0]?.cy ?? null,
        railBottom: allPasses[allPasses.length - 1]?.cy ?? null,
      };
    },
  },

  methods: {
    /**
     * Wrap every word, including long rule identifiers, without discarding
     * trailing lines. Box heights are computed from the resulting line count.
     */
    wrapLines(text: string, max: number): string[] {
      const words = String(text || '')
        .trim()
        .split(/\s+/)
        .filter(Boolean);
      const lines: string[] = [];
      let line = '';
      for (const word of words) {
        const chunks = Array.from(word);
        if (line && line.length + word.length + 1 > max) {
          lines.push(line);
          line = '';
        }
        while (chunks.length > max) {
          lines.push(chunks.splice(0, max).join(''));
        }
        const rest = chunks.join('');
        line = line ? `${line} ${rest}` : rest;
      }
      if (line) lines.push(line);
      return lines;
    },

    successEdgeEnd(cy: number): number {
      return cy >= this.layout.successY &&
        cy <= this.layout.successY + this.TERM_OK_H
        ? this.TERM_OK_X
        : this.RAIL_X;
    },

    noMatchPath(box: FlowPass): string {
      const startY = box.cy + this.DIA_H;
      if (box.nextY === null)
        return `M${this.DIA_CX} ${startY} V${this.layout.noMatchY}`;
      const bendY = Math.max(box.y + box.h, startY) + this.PASS_GAP / 2;
      return `M${this.DIA_CX} ${startY} V${bendY} H${this.COL_X + this.COL_W / 2} V${box.nextY}`;
    },

    diamond(cy: number): string {
      const x = this.DIA_CX;
      const w = this.DIA_W;
      const h = this.DIA_H;
      return `${x},${cy - h} ${x + w},${cy} ${x},${cy + h} ${x - w},${cy}`;
    },

    /**
     * The visual class for a state.
     *
     * `null` — the rule-set view, or a document with no trace — is `none`, not
     * a shade of grey that could be mistaken for "skipped". There is no path,
     * and the diagram says so by drawing none.
     */
    stateClass(state: string | null | undefined): string {
      if (state === 'pass') return 'pass';
      if (state === 'fail') return 'fail';
      if (state === 'skip') return 'skip';
      return 'none';
    },

    /**
     * A glyph that repeats the state without colour.
     *
     * Accessibility, not decoration: printed in greyscale or read by someone
     * who does not distinguish red from green, the diagram still says which
     * stage stopped the document.
     */
    stateMarker(state: string | null | undefined): string {
      if (state === 'pass') return '✓';
      if (state === 'fail') return '✕';
      if (state === 'skip') return '–';
      return '';
    },

    /**
     * What a pass box is called.
     *
     * A stage that runs a single pass gets a sentence about what it compares
     * instead of the pass name: "1.1 Exact" beside a stage called "Total
     * amount match" says nothing the title has not already said.
     */
    boxTitle(stage: PoMatchStage, pass: PoMatchPass, shown: number): string {
      if (shown === 1) {
        const box = BOX_LABELS[stage.key];
        if (box) return pickPoMatchText(box, this.locale);
      }
      return pickPoMatchText(pass.label, this.locale);
    },

    /**
     * The one extra fact on the box: in a document the column that rejected
     * the most pairs with both values, in a cluster nothing (the bar carries
     * the count). A diagram that annotates every box annotates none of them.
     */
    boxDetail(pass: PoMatchPass): string {
      if (this.isCluster) return '';
      const failed = (pass.failed_columns || [])[0];
      if (!failed) return '';
      const column = failed.column_key || failed.column;
      if (failed.expected != null && failed.actual != null) {
        const tolerance =
          failed.tolerance != null ? ` · ±${failed.tolerance}` : '';
        return `${column}: ${failed.expected} → ${failed.actual}${tolerance}`;
      }
      return String(column);
    },

    /** The stage's rules, in the priority order the API sent them. */
    ruleLines(stage: PoMatchStage): string[] {
      const names = (stage.rule_names || []).filter(Boolean);
      if (!names.length) return [this.$t('po_match_flow_no_rules')];
      const max = this.compact ? 2 : 4;
      const shown = names
        .slice(0, max)
        .flatMap((name) => this.wrapLines(name, this.compact ? 23 : 26));
      if (names.length > max) shown.push(`+${names.length - max}`);
      return shown;
    },

    stageTooltip(stage: PoMatchStage): string {
      const parts: string[] = [
        `${stage.no} · ${pickPoMatchText(stage.label, this.locale)}`,
      ];
      const rules = (stage.rule_names || []).filter(Boolean);
      if (rules.length) parts.push(rules.join(', '));
      const skipped = pickPoMatchText(stage.skipped_reason_label, this.locale);
      if (skipped) parts.push(skipped);
      return parts.join(' — ');
    },

    /**
     * Everything the reader needs about one pass, in words.
     *
     * The skipped reason is included verbatim from the API rather than
     * re-derived here: "the engine does not run this pass in this stage" and
     * "the stage ended before this pass ran" look identical on the diagram and
     * mean completely different things.
     */
    passTooltip(stage: PoMatchStage, pass: PoMatchPass): string {
      const parts: string[] = [
        `${stage.no}.${pickPoMatchText(pass.label, this.locale)}`,
      ];
      const skipped = pickPoMatchText(pass.skipped_reason_label, this.locale);
      if (skipped) parts.push(skipped);
      if (pass.matched != null) {
        parts.push(`${this.$t('po_match_flow_matched')}: ${pass.matched}`);
      }
      for (const column of (pass.failed_columns || []).slice(0, 3)) {
        const measured =
          column.expected != null && column.actual != null
            ? ` (${column.expected} / ${column.actual})`
            : '';
        parts.push(`${column.column}: ${column.count}${measured}`);
      }
      if (this.isCluster && pass.doc_count) {
        parts.push(`${pass.doc_count} (${pass.share_pct ?? 0} %)`);
      }
      return parts.join(' — ');
    },

    barWidth(count: number): number {
      const max = this.compact ? 70 : 90;
      if (!this.maxDocCount || !count) return 0;
      return Math.max(3, Math.round((count / this.maxDocCount) * max));
    },

    barLabel(pass: PoMatchPass): string {
      const count = Number(pass.doc_count || 0);
      if (!count) return '';
      return pass.share_pct == null
        ? String(count)
        : `${count} (${pass.share_pct} %)`;
    },

    /**
     * Whether THIS document reached that terminal.
     *
     * Only in document mode: in the rule-set and cluster views neither
     * terminal is "the" outcome, and highlighting one would claim a result for
     * a population that has several.
     */
    terminalReached(key: string): boolean {
      return this.mode === 'document' && this.terminal?.key === key;
    },

    selectPass(band: FlowBand, box: FlowPass): void {
      this.$emit('select-pass', {
        stage: band.key,
        stageNo: band.no,
        pass: box.key,
        state: box.state,
        failedColumns: box.pass.failed_columns || [],
      });
    },
  },
});
</script>

